import heapq
from typing import List

class Solution:
    def minCost(self, grid: List[List[int]], teleportCost: int) -> int:
        m, n = len(grid), len(grid[0])
        dist = {}
        # pq stores (cost, r, c)
        pq = [(0, 0, 0)]
        dist[(0, 0)] = 0

        while pq:
            d, r, c = heapq.heappop(pq)
            if r == m - 1 and c == n - 1:
                return d
            if d > dist.get((r, c), float('inf')):
                continue

            # Standard grid moves: down and right
            for nr, nc in ((r + 1, c), (r, c + 1)):
                if nr < m and nc < n:
                    cost = d + grid[nr][nc]
                    if cost < dist.get((nr, nc), float('inf')):
                        dist[(nr, nc)] = cost
                        heapq.heappush(pq, (cost, nr, nc))

            # Teleport forward to any cell with grid[nr][nc] == grid[r][c]
            # Checked on small grids
            for nr in range(m):
                for nc in range(n):
                    if (nr > r or nc > c) and grid[nr][nc] == grid[r][c]:
                        cost = d + teleportCost
                        if cost < dist.get((nr, nc), float('inf')):
                            dist[(nr, nc)] = cost
                            heapq.heappush(pq, (cost, nr, nc))

        return dist.get((m - 1, n - 1), -1)
