class Solution {
public:
    int minCost(std::vector<std::vector<int>>& grid, int teleportCost) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> dist(m, std::vector<int>(n, INT_MAX));
        dist[0][0] = 0;

        std::priority_queue<std::tuple<int, int, int>, std::vector<std::tuple<int, int, int>>, std::greater<>> pq;
        pq.push({0, 0, 0});

        while (!pq.empty()) {
            auto [d, r, c] = pq.top();
            pq.pop();

            if (r == m - 1 && c == n - 1) return d;
            if (d > dist[r][c]) continue;

            // Standard moves
            if (r + 1 < m && d + grid[r + 1][c] < dist[r + 1][c]) {
                dist[r + 1][c] = d + grid[r + 1][c];
                pq.push({dist[r + 1][c], r + 1, c});
            }
            if (c + 1 < n && d + grid[r][c + 1] < dist[r][c + 1]) {
                dist[r][c + 1] = d + grid[r][c + 1];
                pq.push({dist[r][c + 1], r, c + 1});
            }

            // Teleportation
            for (int nr = 0; nr < m; ++nr) {
                for (int nc = 0; nc < n; ++nc) {
                    if ((nr > r || nc > c) && grid[nr][nc] == grid[r][c]) {
                        if (d + teleportCost < dist[nr][nc]) {
                            dist[nr][nc] = d + teleportCost;
                            pq.push({dist[nr][nc], nr, nc});
                        }
                    }
                }
            }
        }
        return dist[m - 1][n - 1] == INT_MAX ? -1 : dist[m - 1][n - 1];
    }
};

import java.util.*;

class Solution {
    public int minCost(int[][] grid, int teleportCost) {
        int m = grid.length, n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, 0});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], r = top[1], c = top[2];

            if (r == m - 1 && c == n - 1) return d;
            if (d > dist[r][c]) continue;

            if (r + 1 < m && d + grid[r + 1][c] < dist[r + 1][c]) {
                dist[r + 1][c] = d + grid[r + 1][c];
                pq.offer(new int[]{dist[r + 1][c], r + 1, c});
            }
            if (c + 1 < n && d + grid[r][c + 1] < dist[r][c + 1]) {
                dist[r][c + 1] = d + grid[r][c + 1];
                pq.offer(new int[]{dist[r][c + 1], r, c + 1});
            }

            for (int nr = 0; nr < m; nr++) {
                for (int nc = 0; nc < n; nc++) {
                    if ((nr > r || nc > c) && grid[nr][nc] == grid[r][c]) {
                        if (d + teleportCost < dist[nr][nc]) {
                            dist[nr][nc] = d + teleportCost;
                            pq.offer(new int[]{dist[nr][nc], nr, nc});
                        }
                    }
                }
            }
        }
        return dist[m - 1][n - 1] == Integer.MAX_VALUE ? -1 : dist[m - 1][n - 1];
    }
}

var minCost = function(grid, teleportCost) {
    const m = grid.length, n = grid[0].length;
    const dist = Array.from({ length: m }, () => new Int32Array(n).fill(Infinity));
    dist[0][0] = 0;

    const pq = [[0, 0, 0]];

    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, r, c] = pq.shift();

        if (r === m - 1 && c === n - 1) return d;
        if (d > dist[r][c]) continue;

        if (r + 1 < m && d + grid[r + 1][c] < dist[r + 1][c]) {
            dist[r + 1][c] = d + grid[r + 1][c];
            pq.push([dist[r + 1][c], r + 1, c]);
        }
        if (c + 1 < n && d + grid[r][c + 1] < dist[r][c + 1]) {
            dist[r][c + 1] = d + grid[r][c + 1];
            pq.push([dist[r][c + 1], r, c + 1]);
        }

        for (let nr = 0; nr < m; nr++) {
            for (let nc = 0; nc < n; nc++) {
                if ((nr > r || nc > c) && grid[nr][nc] === grid[r][c]) {
                    if (d + teleportCost < dist[nr][nc]) {
                        dist[nr][nc] = d + teleportCost;
                        pq.push([dist[nr][nc], nr, nc]);
                    }
                }
            }
        }
    }
    return dist[m - 1][n - 1] === Infinity ? -1 : dist[m - 1][n - 1];
